    @pytest.mark.asyncio
    async def test_resource_cleanup(self, plugin):
        """
        Scenario: A port is successfully opened.
        Expected: The writer is closed and wait_closed is called to prevent leaks.
        """
        mock_writer = AsyncMock()
        mock_writer.wait_closed = AsyncMock()
        
        with patch('asyncio.open_connection', return_value=(AsyncMock(), mock_writer)):
            await plugin.run("127.0.0.1")
            
            # Verify cleanup sequence
            mock_writer.close.assert_called_once()
            mock_writer.wait_closed.assert_called_once()

